  function applyNaturalVariation(baseText, cycle, tierCount, normLevel, maxLen = 90) {
    if (!baseText || typeof baseText !== 'string') return baseText;
    const trimText = baseText.trim();

    // Đối với câu đã tương đối dài (>= 75 ký tự), câu xếp loại C/CĐ hoặc câu nhận xét chung xuất học bạ (maxLen > 100):
    // Giữ nguyên 100% câu gốc chuẩn mực từ ngân hàng, tuyệt đối KHÔNG ghép từ/cắt ngắn làm biến dạng câu
    if (normLevel === 'C' || normLevel === 'CĐ' || maxLen > 100 || trimText.length >= 75) {
      return trimText;
    }

    // Chuẩn hóa loại bỏ từ 'Em ' hoặc 'Học sinh ' ở đầu câu gốc trước khi thêm tiền tố để tránh lặp từ (ví dụ: 'em em')
    const cleanWithoutSubject = trimText.replace(/^(?:em\s+|học\s*sinh\s+)/i, '');
    const firstCharLower = cleanWithoutSubject.charAt(0).toLowerCase() + cleanWithoutSubject.slice(1);
    const varIdx = (tierCount + cycle) % 8;
    let res = trimText;

    if (normLevel === 'T') {
      switch (varIdx) {
        case 0: res = 'Em ' + firstCharLower; break;
        case 1: res = trimText.replace(/\.?$/, '. Rất đáng khen.'); break;
        case 2: res = 'Rất tích cực: ' + firstCharLower; break;
        case 3: res = trimText.replace(/\.?$/, '. Cần phát huy.'); break;
        case 4: res = 'Luôn chủ động, ' + firstCharLower; break;
        case 5: res = trimText.replace(/\.?$/, '. Đáng biểu dương.'); break;
        case 6: res = 'Chăm ngoan, ' + firstCharLower; break;
        case 7: res = trimText.replace(/\.?$/, '. Tinh thần rất tốt.'); break;
        default: res = 'Em ' + firstCharLower; break;
      }
    } else if (normLevel === 'H' || normLevel === 'Đ' || normLevel === 'K') {
      switch (varIdx) {
        case 0: res = 'Em ' + firstCharLower; break;
        case 1: res = trimText.replace(/\.?$/, '. Cần cố gắng.'); break;
        case 2: res = 'Có cố gắng: ' + firstCharLower; break;
        case 3: res = trimText.replace(/\.?$/, '. Cố gắng chăm chỉ.'); break;
        case 4: res = 'Trong giờ học, em ' + firstCharLower; break;
        case 5: res = trimText.replace(/\.?$/, '. Cần tự giác hơn.'); break;
        case 6: res = 'Học sinh ' + firstCharLower; break;
        case 7: res = trimText.replace(/\.?$/, '. Cố gắng phát huy.'); break;
        default: res = 'Em ' + firstCharLower; break;
      }
    } else {
      return trimText;
    }

    // NGUYÊN TẮC BẢO TOÀN TỪ NGỮ: Nếu biến thể làm câu vượt quá maxLen, trả về câu gốc nguyên vẹn 100%
    // Tuyệt đối không gọi clampToMaxLength cắt bừa bãi làm mất từ cuối của giáo viên
    if (res.length > maxLen) {
      return trimText;
    }

    return res;
  }

  function clampToMaxLength(text, maxLen = 90) {
    if (!text || typeof text !== 'string') return '';
    const trimmed = text.trim();
    if (trimmed.length <= maxLen) return trimmed;

    // 1. Ưu tiên ngắt tại dấu chấm hoàn chỉnh (. ) trước maxLen nếu phần đầu đủ dài (>= 30 ký tự)
    const periodMatch = trimmed.slice(0, maxLen).lastIndexOf('. ');
    if (periodMatch >= 30) {
      return trimmed.slice(0, periodMatch + 1).trim();
    }

    // 2. Ngắt theo dấu chấm phẩy (; ) hoặc phẩy (, )
    const subForPunct = trimmed.slice(0, maxLen);
    const semiMatch = subForPunct.lastIndexOf('; ');
    if (semiMatch >= 30) {
      return trimmed.slice(0, semiMatch).trim() + '.';
    }
    const commaMatch = subForPunct.lastIndexOf(', ');
    if (commaMatch >= 25) {
      let commaPart = trimmed.slice(0, commaMatch).trim();
      // Đảm bảo không kết thúc bằng hư từ lơ lửng
      if (!/\s+(?:và|hoặc|hay|nhưng|với|cùng|của|trong|cho|ở|tại|để|khi|như|về|các|những|thì|mà|rằng|cũng|đã|đang|sẽ)$/i.test(commaPart)) {
        if (!/[.!?]$/.test(commaPart)) commaPart += '.';
        return commaPart;
      }
    }

    // 3. Ngắt theo khoảng trắng (từ ngữ)
    let sub = subForPunct;
    const lastSpace = sub.lastIndexOf(' ');
    if (lastSpace > maxLen * 0.5) {
      sub = sub.slice(0, lastSpace);
    }

    // Chỉ loại bỏ các liên từ / giới từ lơ lửng ở cuối câu (HƯ TỪ THUẦN TÚY)
    // TUYỆT ĐỐI KHÔNG xóa các từ thực từ có nghĩa như: tiến, thể, cân, tự, chuẩn, hoàn, trung...
    const danglingGrammarWords = /\s+(?:và|hoặc|hay|nhưng|với|cùng|của|trong|cho|ở|tại|để|khi|như|về|các|những|thì|mà|rằng|cũng|đã|đang|sẽ|được|theo|do|bởi|từ|lên|xuống|ra|vào)$/i;
    let changed = true;
    while (changed) {
      changed = false;
      if (danglingGrammarWords.test(sub)) {
        sub = sub.replace(danglingGrammarWords, '');
        changed = true;
      }
      sub = sub.replace(/[,;:\-\s]+$/, '');
    }

    if (!/[.!?]$/.test(sub)) sub += '.';

    if (sub.length > maxLen) {
      sub = sub.slice(0, maxLen - 1).replace(/[,;:\-\s]+$/, '') + '.';
    }
    return sub;
  }

  function renderTemplate(templateString, variables = {}) {
    if (!templateString) return '';
    return templateString.replace(/\{\{\s*(\w+)\s*\}\}/g, function (match, key) {
      return variables[key] !== undefined && variables[key] !== null ? variables[key] : '';
    });
  }

  function normalizeSubject(subjectInput, educationLevel = null) {
    if (!subjectInput) return 'DEFAULT';
    const clean = subjectInput.trim();
    const edLevel = (educationLevel || '').toUpperCase();

    // 1. Phẩm chất chủ yếu & Năng lực cốt lõi theo Thông tư 27 / GDPT 2018 (ƯU TIÊN TUYỆT ĐỐI HÀNG ĐẦU)
    if (/chăm\s*chỉ/i.test(clean)) return 'Chăm chỉ';
    if (/yêu\s*nước/i.test(clean)) return 'Yêu nước';
    if (/nhân\s*ái/i.test(clean)) return 'Nhân ái';
    if (/trung\s*thực/i.test(clean)) return 'Trung thực';
    if (/trách\s*nhiệm/i.test(clean)) return 'Trách nhiệm';
    if (/tự\s*chủ|tự\s*học/i.test(clean)) return 'Tự chủ và tự học';
    if (/giao\s*tiếp|hợp\s*tác/i.test(clean)) return 'Giao tiếp và hợp tác';
    if (/sáng\s*tạo|gqvđ|gqvd|giải\s*quyết\s*vấn\s*đề/i.test(clean)) return 'GQVĐ và sáng tạo';
    // 3 bộ danh mục câu nhận xét chung xuất học bạ số theo Thông tư 27 (Ưu tiên độc lập tuyệt đối)
    if (/nhận\s*xét\s*(?:chung\s*)?năng\s*lực\s*đặc\s*thù|nl\s*đặc\s*thù/i.test(clean)) return 'Nhận xét năng lực đặc thù';
    if (/nhận\s*xét\s*chung\s*năng\s*lực|nl_chung|nl\s*chung/i.test(clean)) return 'Nhận xét chung Năng lực';
    if (/nhận\s*xét\s*chung\s*phẩm\s*chất|pc_chung|pc\s*chung/i.test(clean)) return 'Nhận xét chung Phẩm chất';
    if (/năng\s*lực\s*đặc\s*thù/i.test(clean)) return 'Nhận xét năng lực đặc thù';
    if (/^năng\s*lực$/i.test(clean)) return 'Nhận xét chung Năng lực';
    if (/^phẩm\s*chất$/i.test(clean)) return 'Nhận xét chung Phẩm chất';

    // 2. Năng lực đặc thù môn học ánh xạ về môn học tương ứng
    if (/ngôn\s*ngữ/i.test(clean)) return 'Tiếng Việt';
    if (/tính\s*toán/i.test(clean)) return 'Toán';
    if (/thẩm\s*m[ĩỹ]/i.test(clean)) return 'Mĩ thuật';
    if (/thể\s*chất/i.test(clean)) return 'Giáo dục thể chất';
    if (/khoa\s*học/i.test(clean) && /năng\s*lực/i.test(clean)) return edLevel === 'PRIMARY' ? 'Khoa học' : 'Khoa học tự nhiên';
    if (/công\s*nghệ/i.test(clean) && /năng\s*lực/i.test(clean)) return 'Công nghệ';
    if (/tin\s*học/i.test(clean) && /năng\s*lực/i.test(clean)) return 'Tin học';

    // Tăng cường Tiếng Việt (TCTV, TC Tiếng Việt) -> dùng mẫu nhận xét Tiếng Việt
    if (/tăng\s*cường\s*tiếng\s*việt|tctv|tc[\s\-_.]*tv|tc\s*tiếng\s*việt/i.test(clean)) return 'Tiếng Việt';
    if (/tiếng việt/i.test(clean)) return 'Tiếng Việt';
    if (/ngữ văn/i.test(clean)) return 'Ngữ văn';
    if (/văn/i.test(clean)) {
      return edLevel === 'PRIMARY' ? 'Tiếng Việt' : 'Ngữ văn';
    }

    if (/khoa học tự nhiên/i.test(clean) || /\bkhtn\b/i.test(clean)) return 'Khoa học tự nhiên';
    if (/khoa học/i.test(clean)) {
      return (edLevel === 'SECONDARY' || edLevel === 'HIGH_SCHOOL') ? 'Khoa học tự nhiên' : 'Khoa học';
    }

    // Tự nhiên và Xã hội (TN-XH, TNXH, TN - XH)
    if (/tự\s*nhiên\s*(?:và|&)?\s*xã\s*hội|tu\s*nhien\s*(?:va|&)?\s*xa\s*hoi|\btn[\s\-_.]*xh\b|\bt\.?n\.?x\.?h\b/i.test(clean)) return 'Tự nhiên và Xã hội';

    // Tăng cường Toán (TCT, TC Toán) -> dùng mẫu nhận xét Toán
    if (/tăng\s*cường\s*toán|tct|tc[\s\-_.]*t|tc\s*toán/i.test(clean)) return 'Toán';
    if (/toán/i.test(clean)) return 'Toán';
    if (/tiếng pháp/i.test(clean)) return 'Tiếng Pháp';
    if (/tiếng trung|tiếng trung quốc|trung văn/i.test(clean)) return 'Tiếng Trung Quốc';
    if (/tiếng nhật|tiếng nhật bản/i.test(clean)) return 'Tiếng Nhật';
    if (/tiếng hàn|tiếng hàn quốc/i.test(clean)) return 'Tiếng Hàn';
    if (/tiếng nga/i.test(clean)) return 'Tiếng Nga';
    if (/tiếng đức/i.test(clean)) return 'Tiếng Đức';
    if (/ngoại ngữ 1|\bnn1\b/i.test(clean)) return 'Ngoại ngữ 1';
    if (/ngoại ngữ 2|\bnn2\b/i.test(clean)) return 'Ngoại ngữ 2';
    if (/tiếng anh|\bta\b|ngoại ngữ|tiếng nước ngoài/i.test(clean)) return 'Tiếng Anh';
    if (/vật lí|vật lý|\blí\b|\bly\b/i.test(clean)) return 'Vật lí';
    if (/hóa học|\bhóa\b/i.test(clean)) return 'Hóa học';
    if (/sinh học|\bsinh\b/i.test(clean)) return 'Sinh học';

    if (/lịch sử và địa lí|lịch sử & địa lý|\bls&đl\b|\bls-đl\b/i.test(clean)) {
      return 'Lịch sử và Địa lí';
    }
    if (/lịch sử|\bsử\b/i.test(clean)) {
      return edLevel === 'HIGH_SCHOOL' ? 'Lịch sử' : 'Lịch sử và Địa lí';
    }
    if (/địa lí|địa lý|\bđịa\b/i.test(clean)) {
      return edLevel === 'HIGH_SCHOOL' ? 'Địa lí' : 'Lịch sử và Địa lí';
    }

    if (/giáo dục kinh tế|kinh tế và pháp luật|\bgdkt&pl\b|\bgdkt\b/i.test(clean)) {
      return 'Giáo dục kinh tế và pháp luật';
    }
    if (/giáo dục công dân|\bgdcd\b/i.test(clean)) return 'Giáo dục công dân';
    if (/đạo đức/i.test(clean)) return 'Đạo đức';

    if (/tin học|\btin\b/i.test(clean)) return 'Tin học';
    if (/công nghệ/i.test(clean)) return 'Công nghệ';
    if (/giáo\s*dục\s*thể(?:\s*chất)?|\bthể\s*dục\b|\bgdtc\b/i.test(clean)) return 'Giáo dục thể chất';
    if (/quốc phòng|an ninh|\bgdqp\b|\bgdqp-an\b/i.test(clean)) return 'Giáo dục quốc phòng và an ninh';
    if (/chuyên đề|chuyên đề học tập|\bcđht\b/i.test(clean)) return 'Chuyên đề học tập';

    if (/nghệ thuật/i.test(clean)) return 'Nghệ thuật';
    if (/âm nhạc|hát nhạc|nhạc/i.test(clean)) return 'Âm nhạc';
    if (/mĩ thuật|mỹ thuật|vẽ/i.test(clean)) return 'Mĩ thuật';

    if (/trải nghiệm, hướng nghiệp|hđtn, hn|hướng nghiệp/i.test(clean)) {
      return 'Hoạt động trải nghiệm, hướng nghiệp';
    }
    if (/hoạt động trải nghiệm|\bhđtn\b/i.test(clean)) {
      return (edLevel === 'SECONDARY' || edLevel === 'HIGH_SCHOOL')
        ? 'Hoạt động trải nghiệm, hướng nghiệp'
        : 'Hoạt động trải nghiệm';
    }

    if (/giáo dục địa phương|địa phương|\bgdđp\b/i.test(clean)) {
      return 'Nội dung giáo dục địa phương';
    }

    // 3. Môn Tiếng dân tộc (CHỈ khớp khi có 'tiếng dân tộc', 'dtts', hoặc tên dân tộc cụ thể; KHÔNG khớp từ 'chăm' trần)
    if (/tiếng\s*dân\s*tộc|dtts|khmer|tiếng\s*chăm|dân\s*tộc\s*chăm|\bcham\b|ê-đê|ede|ba\s*na|bana|jrai|gia-rai|mông|hmông|thái|mơ\s*nông|tày|nùng|xơ\s*đăng|ca-dong|churu/i.test(clean) && !/chăm\s*chỉ/i.test(clean)) {
      return 'Tiếng dân tộc';
    }
    if (/đánh giá rèn luyện|rèn luyện|hạnh kiểm|gvcn|ý kiến của gvcn|nhận xét của gvcn/i.test(clean)) return 'Đánh giá rèn luyện';

    for (const s of ALL_SUBJECTS_LIST) {
      if (clean.toLowerCase().includes(s.toLowerCase())) return s;
    }
    return 'DEFAULT';
  }

  function normalizeLevelCode(levelInput) {
    if (!levelInput) return 'H';
    const clean = levelInput.trim().toUpperCase();
    if (clean === 'T' || clean === 'TỐT' || clean === 'HOÀN THÀNH TỐT' || clean === 'G' || clean === 'GIỎI' || clean === 'XS' || clean === 'XUẤT SẮC') return 'T';
    if (clean === 'K' || clean === 'KHÁ') return 'K';
    if (clean === 'H' || clean === 'HT' || clean === 'HOÀN THÀNH' || clean === 'TB' || clean === 'TRUNG BÌNH') return 'H';
    if (clean === 'Đ' || clean === 'ĐẠT') return 'Đ';
    if (clean === 'C' || clean === 'CHT' || clean === 'CHƯA HOÀN THÀNH' || clean === 'Y' || clean === 'YẾU' || clean === 'KÉM') return 'C';
    if (clean === 'CĐ' || clean === 'CHƯA ĐẠT') return 'CĐ';
    return 'H';
  }

  /**
   * Sinh nhận xét sư phạm theo môn, mức đánh giá, cấp học, đợt kiểm tra và vị trí học sinh
   * Tự động điều phối chống lặp tuyệt đối và đảm bảo tính phù hợp tiến độ chương trình học.
   */
  
  // =========================================================================
  // NGÂN HÀNG CÂU NHẬN XÉT MỞ RỘNG (THAM KHẢO VÀ CHUYỂN ĐỔI TỪ TYNIX EXTENSION)
